def main():
 p=argparse.ArgumentParser();p.add_argument("--base_model",type=Path,required=True);p.add_argument("--sd2_models",type=Path,required=True);p.add_argument("--msdf_models",type=Path,required=True);p.add_argument("--output",type=Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=True)
 base=UNet2DConditionModel.from_pretrained(a.base_model,subfolder="unet",torch_dtype=torch.float32);adapter=FrozenResidualAdapter();ap=sum(x.numel() for x in adapter.parameters());bp=sum(x.numel() for x in base.parameters())
 audit={"evidence_source":"train_rda.py and checkpoint metadata","vanilla_sd2":{"unet":"full trainable","vae":"frozen","text_encoder":"frozen","optimizer":"AdamW","unet_lr":5e-6,"updates_per_class":2000},"full_msdf":{"unet":"full trainable","vae":"frozen","text_encoder":"frozen","optimizer_groups":{"full_unet":5e-6,"msdf":1e-4},"updates_per_class":2000},"source_identity_can_be_written_into_unet":True,"reason":"all UNet parameters require gradients and are in AdamW group 0; each class is fine-tuned from only its low-shot examples","historical_gradient_data_unavailable":True}
